    EndCheckinPage.prototype.end_visit = function (checkin_id, description) {
        var _this = this;
        this.spinnerLoader = true;
        if (this.image_data.length < 1) {
            this.spinnerLoader = false;
            this.service.errorToast('Please Upload Images !!');
            return;
        }
        if (!description) {
            this.spinnerLoader = false;
            this.service.errorToast('Please Add Description Field !!');
            return;
        }
        this.functionCalled = 1;
        this.locationAccuracy.request(this.locationAccuracy.REQUEST_PRIORITY_HIGH_ACCURACY).then(function () {
            var options = { maximumAge: 10000, timeout: 15000, enableHighAccuracy: true };
            _this.geolocation.getCurrentPosition(options).then(function (resp) {
                var lat = resp.coords.latitude;
                var lng = resp.coords.longitude;
                _this.service.presentLoading();
                _this.service.addData({ 'lat': lat, 'lng': lng, 'checkin_id': checkin_id, 'description': description, imgarr: _this.image_data, 'collection': _this.checkin, 'meet_status': _this.checkin.meet_status }, 'AppCheckin/visitEnd').then(function (result) {
                    if (result['statusCode'] == 200) {
                        _this.spinnerLoader = false;
                        _this.for_order = result['for_order'];
                        _this.brand_assign = result['brand_assign'];
                        _this.service.dismissLoading();
                        _this.service.successToast(result['statusMsg']);
                        if (_this.checkin_data.other_name == '') {
                            if (_this.navCtrl.getViews().length >= 2) {
                                _this.navCtrl.remove(1, 1, { animate: false });
                                _this.navCtrl.pop({ animate: false });
                            }
                            _this.navCtrl.push(__WEBPACK_IMPORTED_MODULE_21__checkin_new_checkin_new__["a" /* CheckinNewPage */]);
                        }
                        else {
                            if (_this.navCtrl.getViews().length >= 2) {
                                _this.navCtrl.remove(1, 1, { animate: false });
                                _this.navCtrl.pop({ animate: false });
                            }
                            _this.navCtrl.push(__WEBPACK_IMPORTED_MODULE_21__checkin_new_checkin_new__["a" /* CheckinNewPage */]);
                            _this.service.dismissLoading();
                        }
                    }
                    else {
                        _this.spinnerLoader = false;
                        _this.service.errorToast(result['statusMsg']);
                        _this.service.dismissLoading();
                    }
                }, function (error) {
                    _this.spinnerLoader = false;
                    _this.service.Error_msg(error);
                    _this.service.dismissLoading();
                });
            }).catch(function (error) {
                _this.spinnerLoader = false;
                _this.service.dismissLoading();
                // this.presentConfirm('Turn On Location permisssion !', 'please go to <strong>Settings</strong> -> Location to turn on <strong>Location permission</strong>')
                _this.geolocation.watchPosition(options).subscribe(function (resp) {
                    var lat = resp.coords.latitude;
                    var lng = resp.coords.longitude;
                    _this.service.presentLoading();
                    _this.service.addData({ 'lat': lat, 'lng': lng, 'checkin_id': checkin_id, 'description': description, imgarr: _this.image_data, 'collection': _this.checkin, 'meet_status': _this.checkin.meet_status }, 'AppCheckin/visitEnd').then(function (result) {
                        if (result['statusCode'] == 200) {
                            _this.spinnerLoader = false;
                            _this.for_order = result['for_order'];
                            _this.brand_assign = result['brand_assign'];
                            _this.service.dismissLoading();
                            _this.service.successToast(result['statusMsg']);
                            if (_this.checkin_data.other_name == '') {
                                // this.viewCtrl.dismiss();
                                // this.appCtrl.getRootNav().push(CheckinNewPage);
                                if (_this.navCtrl.getViews().length >= 2) {
                                    _this.navCtrl.remove(1, 1, { animate: false });
                                    _this.navCtrl.pop({ animate: false });
                                }
                                _this.navCtrl.push(__WEBPACK_IMPORTED_MODULE_21__checkin_new_checkin_new__["a" /* CheckinNewPage */]);
                            }
                            else {
                                if (_this.navCtrl.getViews().length >= 2) {
                                    _this.navCtrl.remove(1, 1, { animate: false });
                                    _this.navCtrl.pop({ animate: false });
                                }
                                _this.navCtrl.push(__WEBPACK_IMPORTED_MODULE_21__checkin_new_checkin_new__["a" /* CheckinNewPage */]);
                                _this.service.dismissLoading();
                            }
                        }
                        else {
                            _this.spinnerLoader = false;
                            _this.service.errorToast(result['statusMsg']);
                            _this.service.dismissLoading();
                        }
                    }, function (error) {
                        _this.spinnerLoader = false;
                        _this.service.Error_msg(error);
                        _this.service.dismissLoading();
                    });
                });
            });
        }, function (error) {
            _this.spinnerLoader = false;
            _this.service.Error_msg(error);
            _this.service.dismissLoading();
        });
    };
    EndCheckinPage.prototype.presentConfirm = function (title, msg) {
        var _this = this;
        var alert = this.alertCtrl.create({
            enableBackdropDismiss: false,
            title: title,
            message: msg,
            cssClass: 'alert-modal',
            buttons: [
                {
                    text: 'Cancel',
                    handler: function () {
                    }
                },
                {
                    text: 'Settings',
                    handler: function () {
                        _this.openSettings();
                    }
                }
            ]
        });
        alert.present();
    };
    EndCheckinPage.prototype.openSettings = function () {
        this.openNativeSettings.open("application_details");
    };
    EndCheckinPage.prototype.openDialer = function (dialnumber, e) {
        e.stopPropagation();
        dialnumber = '' + dialnumber;
        this.callNumber.callNumber(dialnumber, false) // Set to false to allow user to choose app
            .then(function (res) { return console.log('Launched dialer!', res); })
            .catch(function (err) { return console.log('Error launching dialer', err); });
    };
    EndCheckinPage.prototype.captureMedia = function () {
        var _this = this;
        var actionsheet = this.actionSheetController.create({
            title: "Upload Image",
            cssClass: 'cs-actionsheet',
            buttons: [{
                    cssClass: 'sheet-m',
                    text: 'Camera',
                    icon: 'camera',
                    handler: function () {
                        // this.takePhoto();
                        _this.cameraModal();
                    }
                },
                {
                    cssClass: 'sheet-m1',
                    text: 'Gallery',
                    icon: 'image',
                    handler: function () {
                        _this.getImage();
                    }
                },
                {
                    cssClass: 'cs-cancel',
                    text: 'Cancel',
                    role: 'cancel',
                    icon: 'cancel',
                    handler: function () {
                    }
                }
            ]
        });
        actionsheet.present();
    };
    EndCheckinPage.prototype.getImage = function () {
        var _this = this;
        this.diagnostic.requestCameraAuthorization().then(function (isAvailable) {
            console.log(isAvailable);
            var options = {
                quality: 70,
                destinationType: _this.camera.DestinationType.DATA_URL,
                sourceType: _this.camera.PictureSourceType.PHOTOLIBRARY,
                saveToPhotoAlbum: false
            };
            if (_this.Device.platform == 'Android') {
                cordova.plugins.foregroundService.start('Lehar Footwear', 'Camera Service');
            }
            _this.camera.getPicture(options).then(function (imageData) {
                _this.image = 'data:image/jpeg;base64,' + imageData;
                if (_this.Device.platform == 'Android') {
                    cordova.plugins.foregroundService.stop();
                }
                if (_this.image) {
                    _this.fileChange(_this.image);
                }
            }, function (err) {
                if (_this.Device.platform == 'Android') {
                    cordova.plugins.foregroundService.stop();
                }
                if (err == 20) {
                    _this.presentConfirm('Turn On Camera & Media permisssion !', 'Go to <strong>Settings</strong> -> to turn on <strong>Camera permission</strong> & <stong>Files and  media</strong>');
                }
                else {
                    _this.presentConfirm('Error Occured', err);
                }
            });
        });
    };
    EndCheckinPage.prototype.takePhoto = function () {
        var _this = this;
        this.diagnostic.requestCameraAuthorization().then(function (isAvailable) {
            console.log(isAvailable);
            var options = {
                quality: 80,
                destinationType: _this.camera.DestinationType.DATA_URL,
                sourceType: _this.camera.PictureSourceType.CAMERA,
                encodingType: _this.camera.EncodingType.PNG,
                mediaType: _this.camera.MediaType.PICTURE,
                cameraDirection: _this.camera.Direction.FRONT,
                targetWidth: 800,
                targetHeight: 600,
                correctOrientation: true,
            };
            if (_this.Device.platform == 'Android') {
                cordova.plugins.foregroundService.start('Lehar Footwear', 'Camera Service');
            }
            _this.camera.getPicture(options).then(function (imageData) {
                _this.image = 'data:image/jpeg;base64,' + imageData;
                if (_this.Device.platform == 'Android') {
                    cordova.plugins.foregroundService.stop();
                }
                if (_this.image) {
                    _this.fileChange(_this.image);
                }
            }, function (err) {
                if (_this.Device.platform == 'Android') {
                    cordova.plugins.foregroundService.stop();
                }
                if (err == 20) {
                    _this.presentConfirm('Turn On Camera & Media permisssion !', 'Go to <strong>Settings</strong> -> to turn on <strong>Camera permission</strong> & <stong>Files and  media</strong>');
                }
                else {
                    _this.presentConfirm('Error Occured', err);
                }
            });
        });
    };
    EndCheckinPage.prototype.fileChange = function (img) {
        // this.image_data=[];
        this.image_data.push(img);
        this.image = '';
    };
    EndCheckinPage.prototype.remove_image = function (i) {
        this.image_data.splice(i, 1);
    };
    EndCheckinPage.prototype.presentPopover = function (myEvent, type) {
        var _this = this;
        var popover = this.popoverCtrl.create(__WEBPACK_IMPORTED_MODULE_11__expense_popover_expense_popover__["a" /* ExpensePopoverPage */], { 'via': 'checkin', 'checkInData': this.checkin_data, 'showEditRetailer': this.showEditRetailer, 'type': type });
        popover.present({
            ev: myEvent
        });
        popover.onDidDismiss(function (resultData) {
            if (resultData['Retailer'] == 'Show') {
                _this.showEditRetailer = true;
            }
            else if (resultData['Retailer'] == 'Hide') {
                _this.showEditRetailer = false;
            }
        });
    };
    EndCheckinPage.prototype.showLimit = function () {
        console.log('Image Data', this.image_data);
        var alert = this.alertCtrl.create({
            title: 'Alert',
            subTitle: "You can upload only 6 document images",
            cssClass: 'alert-modal',
            buttons: [{
                    text: 'Cancel',
                    role: 'cancel',
                    handler: function () {
                    }
                }
            ]
        });
        alert.present();
    };
