    OrderDetailPage.prototype.getOrderDetail = function (order_id) {
        var _this = this;
        console.log(order_id);
        this.lodingPersent();
        this.service.addData({ "order_id": order_id }, "Order/order_detail").then(function (result) {
            console.log(result);
            _this.orderDetail = result['detail'];
            _this.userDetail = result['data'];
            // this.userDetail.order_total = Math.round(parseFloat(this.userDetail.order_total))
            _this.userDetail.order_grand_totalAfterRoundOff = Math.round(parseFloat(_this.userDetail.order_grand_total));
            _this.userDetail.netBreakup = (parseFloat(_this.userDetail.order_grand_total) / 1.18);
            _this.userDetail.gstBreakup = parseFloat(_this.userDetail.order_grand_total) - parseFloat(_this.userDetail.netBreakup);
            _this.userDetail.disc_percentage = Math.round((parseFloat(_this.userDetail.order_discount) * 100) / parseFloat(_this.userDetail.sub_total));
            console.log(_this.userDetail);
            _this.image = result['images'];
            _this.orderDetail.map(function (item) {
                // item.afterDiscount = parseFloat(item.price)-((parseFloat(item.price)/100)*parseInt(item.discount_percent))
                item.afterDiscount = parseFloat(item.price) - parseFloat(item.discount_amount);
                item.amountAfterRoundOff = Math.round(item.amount);
                item.edit_true = true;
                if (item.dispatch_qty != "0") {
                    _this.show_image = true;
                }
            });
            if (_this.userDetail.company_name) {
                _this.tag = _this.userDetail.company_name[0].toUpperCase();
            }
            _this.orderDate = __WEBPACK_IMPORTED_MODULE_5_moment___default()(_this.userDetail.order_date_created).format("YY:MM:DD");
            console.log(_this.orderDate);
            _this.loading.dismiss();
        });
    };
