    OrderDetailPage.prototype.presentAlert = function () {
        var alert = this.alertCtrl.create({
            title: 'Alert',
            subTitle: 'Order is already saved in Cart',
            buttons: ['Dismiss']
        });
        alert.present();
    };
    OrderDetailPage.prototype.add_new_item = function (order_id, dr_id) {
        var _this = this;
        if (this.order_item_array == '') {
            this.service.addData({ 'dr_id': dr_id }, 'Order/user_detail').then(function (result) {
                console.log(result);
                _this.user_data = result['data'];
                _this.brand_assign = result['brand_assign'];
                _this.navCtrl.push(__WEBPACK_IMPORTED_MODULE_3__add_order_add_order__["a" /* AddOrderPage */], { 'data': _this.user_data, 'order_id': order_id, 'brand_assign': _this.brand_assign });
            });
        }
        else {
            this.presentAlert();
        }
    };
    OrderDetailPage.prototype.presentToast = function () {
        var toast = this.toastCtrl.create({
            message: 'Order Item Updated Successfully',
            duration: 3000,
            position: 'bottom'
        });
        toast.present();
    };
    OrderDetailPage.prototype.presentToast1 = function () {
        var toast = this.toastCtrl.create({
            message: 'Order Item Deleted Successfully',
            duration: 3000,
            position: 'bottom'
        });
        toast.present();
    };
    OrderDetailPage.prototype.update_order = function (index, order_id, order_item_id, del) {
        var _this = this;
        if (!this.orderDetail[index].qty && del == false) {
            this.service.presentToast('Please Enter Valid Quantity');
            return;
        }
        this.lodingPersent();
        this.service.addData({ 'order_id': order_id, 'order_item_id': order_item_id, 'item': this.orderDetail[index], 'order': this.userDetail, delete: del, loginId: this.constant.UserLoggedInData.id }, 'Order/update_order_item')
            .then(function (result) {
            console.log(result);
            if (result[1] === 0) {
                _this.navCtrl.pop();
                _this.loading.dismiss();
                _this.service.presentToast('Order Deleted Sucessfully');
                return;
            }
            if (result[0] == 'success') {
                _this.loading.dismiss();
                if (del == false) {
                    _this.presentToast();
                }
                else {
                    _this.service.presentToast('Order Item Deleted Sucessfully');
                }
                _this.getOrderDetail(order_id);
            }
        });
        this.active = {};
        this.orderDetail[index].edit_true = true;
    };
    OrderDetailPage.prototype.delete_item = function (index, order_id, order_item_id) {
        var _this = this;
        var alert = this.alertCtrl.create({
            title: 'Confirm ',
            message: 'Are you sure you want to delete this item ?',
            buttons: [
                {
                    text: 'No',
                    handler: function () {
                        console.log('Cancel clicked');
                    }
                },
                {
                    text: 'Yes',
                    handler: function () {
                        _this.orderDetail[index].qty = 0;
                        var data = { index: index, order_id: order_id, order_item_id: order_item_id };
                        _this.calculateAmount(0, index, true, data);
                        // this.delete_order_item(index,order_id,order_item_id);
                    }
                }
            ]
        });
        alert.present();
    };
    OrderDetailPage.prototype.delete_order_item = function (index, order_id, order_item_id) {
        var _this = this;
        this.lodingPersent();
        this.service.addData({ 'order_id': order_id, 'order_item_id': order_item_id }, 'Order/delete_order_item').then(function (result) {
            console.log(result);
            if (result == 'success') {
                _this.orderDetail.splice(index, 1);
                _this.loading.dismiss();
                _this.presentToast1();
                _this.getOrderDetail(order_id);
            }
        });
    };
    OrderDetailPage.prototype.forceDispatch = function () {
        var _this = this;
        var alert = this.alertCtrl.create({
            title: 'Are You Sure?',
            subTitle: 'You want To Dispatch Order Manually?',
            cssClass: 'action-close',
            buttons: [{
                    text: 'Cancel',
                    role: 'cancel',
                    handler: function () {
                        _this.service.presentToast('Action Cancelled');
                    }
                },
                {
                    text: 'Confirm',
                    cssClass: 'close-action-sheet',
                    handler: function () {
                        _this.service.addData({ id: _this.userDetail.order_id }, 'dealerData/changeStatusToDispatch')
                            .then(function (result) {
                            _this.service.presentToast('Order Dispatched Successfully');
                            _this.userDetail.order_status = 'Dispatch';
                            _this.getOrderDetail(_this.userDetail.order_id);
                        }, function (err) {
                        });
                    }
                }]
        });
        alert.present();
    };
    OrderDetailPage.prototype.check_num = function (indx) {
        console.log(this.orderDetail[indx]);
        if (this.orderDetail[indx]['pending_qty'] < this.orderDetail[indx]['disp_qty']) {
            var toast = this.toastCtrl.create({
                message: 'Invalid Qty',
                duration: 3000,
                position: 'bottom'
            });
            toast.present();
            this.orderDetail[indx]['disp_qty'] = this.orderDetail[indx]['pending_qty'];
        }
    };
    OrderDetailPage.prototype.dispatch_item = function () {
        var _this = this;
        console.log(this.orderDetail);
        this.service.addData({ "item": this.orderDetail }, "dealerData/dispatch_order")
            .then(function (resp) {
            console.log(resp);
            if (resp['msg'] == "success") {
                console.log(_this.constant.rootUrlSfa + 'dealerData/upload_invoice?id=' + resp['order_id'] + '&created_type=' + _this.userType + '&created_by=' + _this.loginData.id);
                if (_this.image.length > 0) {
                    _this.image.forEach(function (element) {
                        var fileTransfer = _this.transfer.create();
                        var random = Math.floor(Math.random() * 100);
                        var options = {
                            fileKey: 'photo',
                            fileName: "myImage_" + random + ".jpg",
                            chunkedMode: false,
                            mimeType: "image/jpeg",
                        };
                        fileTransfer.upload(element, _this.constant.rootUrlSfa + 'dealerData/upload_invoice?id=' + resp['order_id'] + '&created_type=' + _this.userType + '&created_by=' + _this.loginData.id, options)
                            .then(function (data) {
                            console.log(data);
                            console.log("success");
                        }, function (err) {
                            console.log(err);
                            console.log("error");
                        });
                    });
                }
                var toast = _this.toastCtrl.create({
                    message: 'Order Item Dispatched Successfully',
                    duration: 3000,
                    position: 'bottom'
                });
                toast.present();
                _this.getOrderDetail(_this.order_id);
                _this.dispatch = false;
            }
        });
    };
