    OrderDetailPage.prototype.updateStatus = function (status, reason, remark, pre_close_remark) {
        var _this = this;
        console.log(this.constant.UserLoggedInData.id);
        if (!status) {
            this.service.presentToast('Select Status');
            return;
        }
        var str = status;
        var str1;
        if (status == 'Approved') {
            str = 'accept';
            str1 = 'accepted';
        }
        else if (status == 'Pre Close') {
            str = 'pre close';
            str1 = 'pre closed';
        }
        else {
            str = 'refer back';
            str1 = 'referred back';
        }
        if (status == 'Reject' && !reason) {
            this.service.presentToast('Refer back reason required !!');
            return;
        }
        if (status == 'Pre Close' && !pre_close_remark) {
            this.service.presentToast('Pre close reason required !!');
            return;
        }
        var alert = this.alertCtrl.create({
            title: 'Are You Sure!',
            subTitle: "You want to " + str + " order ?",
            cssClass: 'action-close',
            buttons: [{
                    text: 'Cancel',
                    role: 'cancel',
                    handler: function () {
                        _this.userDetail.changeStatus = false;
                        _this.service.presentToast('Order not ' + str1);
                    }
                },
                {
                    text: 'Confirm',
                    cssClass: 'close-action-sheet',
                    handler: function () {
                        console.log(_this.userDetail.order_id);
                        _this.userDetail.changeStatus = false;
                        _this.service.show_loading();
                        _this.service.addData({ id: _this.userDetail.order_id, status: status, reason: reason, reamrk: remark, pre_close_remark: pre_close_remark, loginId: _this.constant.UserLoggedInData.id }, 'dealerData/changeStatusOrder')
                            .then(function (result) {
                            if (_this.userDetail.reason_reject1 != '') {
                                _this.userDetail.reason_reject = _this.userDetail.reason_reject1;
                            }
                            else {
                                _this.userDetail.reason_reject = '';
                            }
                            if (_this.userDetail.remark1 != '') {
                                _this.userDetail.remark = _this.userDetail.remark1;
                            }
                            else {
                                _this.userDetail.remark = '';
                            }
                            _this.service.presentToast('Order Status Updated Successfully');
                            _this.service.dismiss();
                            _this.userDetail.order_status = status;
                            if (result[1]) {
                                _this.userDetail.order_no = result[1];
                            }
                            _this.getOrderDetail(_this.userDetail.order_id);
                        }, function (err) {
                            _this.userDetail.changeStatus = false;
                            _this.service.dismiss();
                            _this.service.errToasr();
                        });
                    }
                }]
        });
        alert.present();
    };
