    SecondaryOrderAddPage.prototype.distributors = function (masterSearch) {
        var _this = this;
        if (this.navParams.get('checkin_id') || (this.navParams.get('Dist_login'))) {
            console.log(this.data);
            this.service.addData({ 'dr_type': this.data.networkType, 'checkin_dr_id': this.navParams.get('id'), 'master_search': masterSearch }, 'AppOrder/followupCustomer').then(function (result) {
                if (result['statusCode'] == 200) {
                    _this.drList = result['result'];
                    var Index = _this.drList.findIndex(function (row) { return row.id == _this.retailerID; });
                    if (Index != -1) {
                        _this.data.type_name = _this.drList[Index];
                        _this.get_distributor_list(_this.retailerID);
                    }
                    else {
                    }
                }
                else {
                    _this.service.errorToast(result['statusMsg']);
                }
            });
        }
        else {
            if (this.Dr_Data.type != 1) {
                this.Dr_type;
                this.service.addData({ 'dr_type': this.data.networkType, 'master_search': masterSearch }, 'AppOrder/followupCustomer').then(function (result) {
                    _this.drList = result['result'];
                });
            }
            else {
                this.Dr_type;
                this.service.addData({ 'dr_type': '3', 'master_search': masterSearch }, 'AppOrder/assignedDealer').then(function (result) {
                    _this.drList = result['result'];
                });
            }
        }
    };
