    SecondaryOrderAddPage.prototype.get_distributor_list = function (id) {
        var _this = this;
        var retailer_id;
        if (this.navParams.get('checkin_id')) {
            retailer_id = id;
        }
        else if (this.navParams.get('Dist_login')) {
            retailer_id = id;
        }
        else {
            retailer_id = id.id;
        }
        this.service.presentLoading();
        this.service.addData({ 'dealer_id': retailer_id, }, 'AppOrder/getAssignDistributor').then(function (result) {
            if (result['statusCode'] == 200) {
                _this.service.dismissLoading();
                _this.Distributor_list = result['distributor_arr'];
                if (_this.Dr_Data.type == 1) {
                    var index = _this.Distributor_list.findIndex(function (r) { return r.id == _this.Dr_Data.id; });
                    _this.data.distributor_id = _this.Distributor_list[index];
                }
            }
            else {
                _this.service.dismissLoading();
                _this.service.errorToast(result['statusMsg']);
            }
        }, function (err) {
            _this.service.dismissLoading();
        });
    };
