    SecondaryOrderAddPage.prototype.backAction = function () {
        var _this = this;
        if (this.add_list.length > 0) {
            var alert_1 = this.alertCtrl.create({
                title: 'Are You Sure?',
                subTitle: 'Your Order Data Will Be Lost ',
                cssClass: 'alert-modal',
                buttons: [{
                        text: 'No',
                        role: 'cancel',
                        handler: function () {
                            _this.service.presentToast('Your Data is Safe');
                        }
                    },
                    {
                        text: 'Yes',
                        cssClass: 'close-action-sheet',
                        handler: function () {
                            _this.navCtrl.pop();
                        }
                    }]
            });
            alert_1.present();
        }
        else {
            this.navCtrl.pop();
        }
    };
