    SecondaryOrderAddPage.prototype.save_orderalert = function (type) {
        var _this = this;
        var str;
        if (this.grand_total > 20000000) {
            var alert_2 = this.alertCtrl.create({
                title: 'Max order value reached',
                subTitle: 'Maximum order value is 2 Cr. !',
                cssClass: 'alert-modal',
                buttons: [{
                        text: 'Okay',
                        role: 'Okay',
                        handler: function () {
                        }
                    },
                ]
            });
            alert_2.present();
            return;
        }
        if (type == 'draft') {
            str = 'You want to save this order as draft ?';
        }
        else {
            str = 'You want to submit this order ?';
        }
        var alert = this.alertCtrl.create({
            title: 'Are You Sure?',
            subTitle: str,
            cssClass: 'alert-modal',
            buttons: [{
                    text: 'Cancel',
                    role: 'cancel',
                    handler: function () {
                    }
                },
                {
                    text: 'Confirm',
                    cssClass: 'close-action-sheet',
                    handler: function () {
                        _this.save_order(type);
                    }
                }]
        });
        alert.present();
    };
