    SecondaryOrderAddPage.prototype.OnlyNumber = function (event) {
        var pattern = /[0-9]+/;
        var inputChar = String.fromCharCode(event.charCode);
        if (event.keyCode != 8 && !pattern.test(inputChar)) {
            event.preventDefault();
        }
    };
