    AddCheckinPage.prototype.presentConfirm = function (title, msg) {
        var _this = this;
        var alert = this.alertCtrl.create({
            enableBackdropDismiss: false,
            title: title,
            message: msg,
            cssClass: 'alert-modal',
            buttons: [
                {
                    text: 'Cancel',
                    handler: function () {
                    }
                },
                {
                    text: 'Settings',
                    handler: function () {
                        _this.openSettings();
                    }
                }
            ]
        });
        alert.present();
    };
    AddCheckinPage.prototype.openSettings = function () {
        this.openNativeSettings.open("application_details");
    };
    AddCheckinPage.prototype.getSateteDistrcit = function () {
        var _this = this;
        if (this.form.pincode.length == 6) {
            this.form1.pincode = this.form.pincode;
            this.service.addData(this.form1, "AppCustomerNetwork/getStateDistict")
                .then(function (resp) {
                if (resp['statusCode'] == 200) {
                    _this.form.state = resp['result'].state_name;
                    _this.form.district = resp['result'].district_name;
                }
                else {
                    _this.service.errorToast(resp['statusMsg']);
                }
            }, function (err) {
                _this.service.errorToast('Something Went Wrong!');
            });
        }
    };
