    // Update quantity of item
    ProductSalePage.prototype.updateQuantity = function (item, change) {
        var newQuantity = item.quantity + change;
        if (newQuantity <= 0) {
            this.deleteItem(item);
            return;
        }
        var availableStock = parseInt(item.stock) || 0;
        if (newQuantity > availableStock) {
            this.service.errorToast("Maximum stock available is " + availableStock);
            return;
        }
        item.quantity = newQuantity;
        item.total_amount = item.quantity * item.price;
        this.saveCartToStorage();
    };
    // Handle direct quantity input
    ProductSalePage.prototype.onQuantityInput = function (item, event) {
        var quantity = parseInt(event.target.value) || 0;
        var availableStock = parseInt(item.stock) || 0;
        if (quantity <= 0) {
            this.deleteItem(item);
            return;
        }
        if (quantity > availableStock) {
            this.service.errorToast("Maximum stock available is " + availableStock);
            quantity = availableStock;
        }
        item.quantity = quantity;
        item.total_amount = item.quantity * item.price;
        event.target.value = quantity;
        this.saveCartToStorage();
    };
