    PrimaryAddItemPage.prototype.takePhoto = function () {
        var _this = this;
        var options = {
            // quality: 70,
            // destinationType: this.camera.DestinationType.DATA_URL,
            // targetWidth: 500,
            // targetHeight: 400,
            // cameraDirection: 1,
            // correctOrientation: true
            quality: 50,
            destinationType: this.camera.DestinationType.DATA_URL,
            targetWidth: 800,
            targetHeight: 600,
            allowEdit: false
        };
        if (this.Device.platform == 'Android') {
            cordova.plugins.foregroundService.start('Soulwud', 'Camera Service');
        }
        this.camera.getPicture(options).then(function (imageData) {
            _this.image = 'data:image/jpeg;base64,' + imageData;
            if (_this.Device.platform == 'Android') {
                cordova.plugins.foregroundService.stop();
            }
            if (_this.image) {
                _this.fileChange(_this.image);
            }
        }, function (err) {
            if (_this.Device.platform == 'Android') {
                cordova.plugins.foregroundService.stop();
            }
        });
    };
    PrimaryAddItemPage.prototype.getImage = function () {
        var _this = this;
        var options = {
            quality: 70,
            destinationType: this.camera.DestinationType.DATA_URL,
            sourceType: this.camera.PictureSourceType.PHOTOLIBRARY,
            saveToPhotoAlbum: false,
            cameraDirection: 1,
            correctOrientation: true
        };
        if (this.Device.platform == 'Android') {
            cordova.plugins.foregroundService.start('Soulwud', 'Camera Service');
        }
        this.camera.getPicture(options).then(function (imageData) {
            _this.image = 'data:image/jpeg;base64,' + imageData;
            if (_this.Device.platform == 'Android') {
                cordova.plugins.foregroundService.stop();
            }
            if (_this.image) {
                _this.fileChange(_this.image);
            }
        }, function (err) {
            if (_this.Device.platform == 'Android') {
                cordova.plugins.foregroundService.stop();
            }
        });
    };
